-- Blog images and links off the old WordPress site.
-- The 58 images the blog loaded from www.royalwoodshop.com/wp-content/uploads/
-- now live in public/uploads/blog/ (WebP), and the 23 links inside posts that
-- pointed at the old site now point at the matching page on this one. Without this,
-- every one of them breaks when the domain moves off WP Engine.
-- The same rewrite was applied to src/data/posts.json. Safe to re-run: the second
-- time nothing matches.
UPDATE posts SET content_html = regexp_replace(content_html, 'https?://(www\.)?royalwoodshop\.com/wp-content/uploads/', 'https://www.royalwoodshop.com/wp-content/uploads/', 'g'), featured_image = regexp_replace(featured_image, 'https?://(www\.)?royalwoodshop\.com/wp-content/uploads/', 'https://www.royalwoodshop.com/wp-content/uploads/', 'g') WHERE content_html ~ 'royalwoodshop\.com/wp-content/uploads/' OR featured_image ~ 'royalwoodshop\.com/wp-content/uploads/';
--> statement-breakpoint
